import { GIFEncoder, quantize, applyPalette } from './gifenc.js';
let gif,options,frame=0;
self.onmessage=e=>{const{id,type}=e.data;try{if(type==='init'){options=e.data;gif=GIFEncoder();frame=0;self.postMessage({id});return}if(type==='frame'){const pixels=new Uint8ClampedArray(e.data.buffer),palette=quantize(pixels,options.colors,{format:'rgba4444',oneBitAlpha:false}),index=applyPalette(pixels,palette,'rgba4444');gif.writeFrame(index,options.width,options.height,{palette,delay:1000/options.fps,repeat:frame++===0?(options.loop?0:-1):undefined});self.postMessage({id});return}if(type==='finish'){gif.finish();const bytes=gif.bytesView(),copy=bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength);self.postMessage({id,buffer:copy},[copy]);gif=null}}catch(err){self.postMessage({id,error:err?.message||String(err)})}};
